"""Bounded installation records, canonical path maps, and read-only availability."""

from __future__ import annotations

import json
import re
import stat
import threading
from dataclasses import asdict
from pathlib import PurePosixPath

from .bundle import BundleLimits, ValidatedBundle, _manifest
from .paths import WorkshopError, WorkshopPaths, identity, read_json, write_json

REGISTRY_SCHEMA = "neko.model.installed.v1"
JOURNAL_SCHEMA = "neko.model.install.v1"
STATE_BYTES = 16 * 1024 * 1024
MAX_INSTALLED = 1024


def task_id(value):
    """Local attempt IDs are generated by the service, never accepted from a package."""
    if not isinstance(value, str) or re.fullmatch("[0-9a-f]{32}", value) is None:
        raise WorkshopError("model_workshop_state_unreadable")
    return value


def make_record(bundle: ValidatedBundle, attempt: str) -> dict:
    """Preserve binary bytes and nested parents; only the MMD main basename changes."""
    task_id(attempt)
    if not re.fullmatch("[0-9a-f]{64}", bundle.sha256):
        raise WorkshopError("model_workshop_state_unreadable")
    name = "neko_model_" + bundle.sha256
    entry = PurePosixPath(bundle.entrypoint)
    if bundle.model_format == "vrm":
        target = "vrm/" + name + ".vrm"
        mapping = {bundle.entrypoint: target}
    else:
        target = ("live2d/" if bundle.model_format == "live2d" else "mmd/") + name
        mapping = {item.path: target + "/" + item.path for item in bundle.files}
        if bundle.model_format == "mmd":
            renamed = entry.with_name(name + entry.suffix).as_posix()
            mapping[bundle.entrypoint] = target + "/" + renamed
    return dict(
        package_sha256=bundle.sha256,
        install_id=attempt,
        installer_version=1,
        model_format=bundle.model_format,
        entrypoint=bundle.entrypoint,
        target=target,
        local_entrypoint=mapping[bundle.entrypoint],
        display_name=bundle.display_name,
        attribution=bundle.attribution,
        license=bundle.license,
        files=[
            dict(asdict(item), local_path=mapping[item.path]) for item in bundle.files
        ],
    )


def validate_record(record) -> dict:
    """Rebuild the canonical map; untrusted JSON cannot supply a recovery/deletion path."""
    try:
        if (
            not isinstance(record, dict)
            or type(record.get("installer_version")) is not int
        ):
            raise ValueError
        files = record["files"]
        manifest = {
            key: record[key]
            for key in (
                "model_format",
                "entrypoint",
                "display_name",
                "attribution",
                "license",
            )
        }
        manifest.update(
            schema="neko.model.package.v1",
            files=[
                {key: item[key] for key in ("path", "byte_size", "sha256")}
                for item in files
            ],
        )
        raw = json.dumps(manifest, ensure_ascii=False).encode()
        if len(raw) > BundleLimits().manifest_bytes:
            raise ValueError
        data, inventory = _manifest(raw, BundleLimits())
        bundle = ValidatedBundle(
            data["model_format"],
            data["entrypoint"],
            data["display_name"],
            data["attribution"],
            data["license"],
            inventory,
            0,
            record["package_sha256"],
        )
        expected = make_record(bundle, record["install_id"])
        if (
            record != expected
            or sum(item.byte_size for item in inventory) > BundleLimits().unpacked_bytes
        ):
            raise ValueError
        return record
    except (ValueError, TypeError, KeyError, AttributeError, RecursionError) as exc:
        raise WorkshopError("model_workshop_state_unreadable") from exc


def validate_journal(data, filename: str) -> dict:
    """Only recognized phases and platform object identities are usable recovery evidence."""
    try:
        if not isinstance(data, dict) or set(data) != {
            "schema",
            "task_id",
            "phase",
            "stage_identity",
            "record",
            "object_identity",
        }:
            raise ValueError
        if (
            data["schema"] != JOURNAL_SCHEMA
            or task_id(data["task_id"]) + ".json" != filename
        ):
            raise ValueError
        if data["phase"] not in (
            "receiving",
            "queued",
            "validating",
            "staging",
            "committing",
        ):
            raise ValueError
        for key in ("stage_identity", "object_identity"):
            value = data[key]
            if (
                key == "object_identity"
                and value is None
                and data["phase"] != "committing"
            ):
                continue
            if (
                not isinstance(value, list)
                or len(value) != 3
                or any(type(n) is not int or n < 0 for n in value)
            ):
                raise ValueError
            if not value[1] or value[2] not in (stat.S_IFDIR, stat.S_IFREG):
                raise ValueError
        if data["stage_identity"][2] != stat.S_IFDIR:
            raise ValueError
        if data["record"] is not None:
            validate_record(data["record"])
            if data["record"]["install_id"] != data["task_id"]:
                raise ValueError
        if data["phase"] in ("staging", "committing") and data["record"] is None:
            raise ValueError
        if data["phase"] == "committing":
            kind = (
                stat.S_IFREG
                if data["record"]["model_format"] == "vrm"
                else stat.S_IFDIR
            )
            if data["object_identity"][2] != kind:
                raise ValueError
        return data
    except (ValueError, TypeError, KeyError, AttributeError) as exc:
        raise WorkshopError("model_workshop_state_unreadable") from exc


class Registry:
    """One short merge lock shared by install/recovery and the later delete adapter."""

    def __init__(self, paths: WorkshopPaths):
        self.paths = paths
        self.lock = threading.RLock()

    def read(self) -> dict:
        data = read_json(
            self.paths.checked("model_workshop/installed.json"), STATE_BYTES
        )
        if data is None:
            return dict(installed={}, attempts={})
        if (
            not isinstance(data, dict)
            or set(data) != {"schema", "installed", "attempts"}
            or data["schema"] != REGISTRY_SCHEMA
        ):
            raise WorkshopError("model_workshop_state_unreadable")
        rows = data["installed"]
        if not isinstance(rows, dict) or len(rows) > MAX_INSTALLED:
            raise WorkshopError("model_workshop_state_unreadable")
        for key, value in rows.items():
            if validate_record(value)["package_sha256"] != key:
                raise WorkshopError("model_workshop_state_unreadable")
        attempts = data["attempts"]
        if (
            not isinstance(attempts, dict)
            or len(attempts) > MAX_INSTALLED
            or not set(rows) <= set(attempts)
        ):
            raise WorkshopError("model_workshop_state_unreadable")
        for digest, attempt in attempts.items():
            if re.fullmatch("[0-9a-f]{64}", digest) is None:
                raise WorkshopError("model_workshop_state_unreadable")
            task_id(attempt)
        return dict(installed=rows, attempts=attempts)

    def load(self) -> dict:
        return self.read()["installed"]

    def save(self, rows: dict, attempts=None) -> None:
        if attempts is None:
            attempts = self.read()["attempts"]
        self.check_capacity(rows, attempts)
        write_json(
            self.paths.checked("model_workshop/installed.json"),
            dict(schema=REGISTRY_SCHEMA, installed=rows, attempts=attempts),
            STATE_BYTES,
        )

    @staticmethod
    def check_capacity(rows: dict, attempts=None) -> None:
        # Check before publishing resources, as metadata failure must not create
        # a model which can never be committed to the bounded registry.
        if attempts is None:
            attempts = {key: row["install_id"] for key, row in rows.items()}
        if (
            max(len(rows), len(attempts)) > MAX_INSTALLED
            or len(
                json.dumps(
                    dict(schema=REGISTRY_SCHEMA, installed=rows, attempts=attempts),
                    ensure_ascii=False,
                ).encode()
            )
            > STATE_BYTES
        ):
            raise WorkshopError("model_workshop_state_too_large")

    def journals(self) -> list[dict]:
        directory = self.paths.checked("model_workshop/transactions")
        if not directory.exists():
            return []
        names = list(directory.iterdir())
        if len(names) > MAX_INSTALLED:
            raise WorkshopError("model_workshop_state_unreadable")
        return [
            validate_journal(
                read_json(
                    self.paths.checked("model_workshop/transactions/" + name.name),
                    STATE_BYTES,
                ),
                name.name,
            )
            for name in sorted(names)
            if name.suffix == ".json"
        ]

    def status(self, record: dict) -> str:
        """Completed models may be edited locally; existence never implies original hashes."""
        try:
            for item in record["files"]:
                if identity(self.paths.checked(item["local_path"]))[2] != stat.S_IFREG:
                    return "missing"
            return "installed"
        except FileNotFoundError:
            return "missing"

    def installed(self) -> list[dict]:
        with self.lock:
            state = self.read()
            return [
                dict(
                    row,
                    status=self.status(row)
                    if state["attempts"][key] == row["install_id"]
                    else "unavailable",
                )
                for key, row in state["installed"].items()
            ]

    def unavailable(self) -> set[str]:
        """Read-only paths for N3/Monitor: no prefix inference, recovery or directory creation."""
        with self.lock:

            def snapshot():
                try:
                    return self.read()
                except WorkshopError:
                    return dict(installed={}, attempts={})

            # Monitor has no writer lock. Retry a metadata change across the
            # journal scan so an older completion cannot expose a new attempt.
            for _ in range(3):
                state = snapshot()
                journals = self.journals()
                if state == snapshot():
                    break
            else:
                raise WorkshopError("model_workshop_state_busy")
            rows, attempts = state["installed"], state["attempts"]
            result = set()
            for journal in journals:
                record = journal["record"]
                if record is not None and journal["phase"] == "committing":
                    completed = rows.get(record["package_sha256"])
                    if (
                        completed is None
                        or completed["install_id"] != record["install_id"]
                    ) and attempts.get(
                        record["package_sha256"], record["install_id"]
                    ) == record["install_id"]:
                        result.add(record["target"])
                    # Any completed attempt, including a newer installation, wins
                    # over old physical IDs which cannot survive a storage copy.
            return result
